code.java:
class Solution {
    public int removeElement(int[] nums, int val) {
        int write = 0;
        for (int value : nums) if (value != val) nums[write++] = value;
        return write;
    }
}

code.kotlin:
class Solution {
    fun removeElement(nums: IntArray, value: Int): Int {
        var write = 0
        for (item in nums) if (item != value) nums[write++] = item
        return write
    }
}

